<?php $title='Users';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Manage Staff</h1><p>Users, roles, activation and security.</p></div><a class="primary" href="<?=route('admin.user.create')?>">+ Add user</a></div><div class="panel table-wrap"><table><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Last login</th><th></th></tr><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?><div class="muted"><?=e($u['username'])?></div></td><td><?=e($u['email'])?></td><td><?=e($u['role_name'])?></td><td><?=!empty($u['is_banned'])?'Banned':(!empty($u['is_active'])?'Active':'Inactive')?></td><td><?=e($u['last_login'])?></td><td><a href="<?=route('admin.user.edit',['id'=>$u['id']])?>">Edit</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../layouts/footer.php';?>
